#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Removes Tracker Calibration. Trackers behave as before. Your calibration stays in ~/.config/fbt-calibrator.
DRV="$HOME/.local/share/SteamVR/drivers/fbtcal"
pkill -x fbt-calibrator
for root in "$HOME/.local/share/Steam" "$HOME/.steam/steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
  for lib in "$root" $(grep -o '"path"[[:space:]]*"[^"]*"' "$root/steamapps/libraryfolders.vdf" 2>/dev/null | cut -d'"' -f4); do
    r="$lib/steamapps/common/SteamVR/bin/vrpathreg.sh"
    [ -x "$r" ] && "$r" removedriver "$DRV" >/dev/null 2>&1
  done
done
rm -rf "$DRV" "$HOME/.local/share/fbt-calibrator" /dev/shm/fbtcal-v1
rm -f "$HOME/.local/bin/fbt-calibrator" "$HOME/.local/share/applications/fbt-calibrator.desktop" \
      "$HOME/.config/autostart/fbt-calibrator.desktop"
CFG="$HOME/.config/vr-autolauncher/config.json"
[ -f "$CFG" ] && python3 - "$CFG" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
d["apps"] = [a for a in d["apps"] if a["name"] not in ("Калібрування трекерів", "Tracker Calibration")]
json.dump(d, open(sys.argv[1], "w"), indent=1, ensure_ascii=False)
PY
echo "Removed. Restart SteamVR. / Прибрано. Перезапусти SteamVR."
